* {
  box-sizing: border-box;
}

body {
  margin: 0;
}

.catalog-page {
  min-height: 100vh;
  background: #f6f7f9;
  color: #18212f;
  font-family: Arial, Helvetica, sans-serif;
}

.catalog-container {
  max-width: 1100px;
  margin: 0 auto;
  padding: 64px 24px;
}

.catalog-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 32px;
  margin-bottom: 32px;
}

.catalog-eyebrow {
  margin: 0 0 12px;
  color: #667085;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: .04em;
  text-transform: uppercase;
}

.catalog-header h1 {
  margin: 0;
  font-size: 36px;
  letter-spacing: -.03em;
}

.catalog-description {
  max-width: 620px;
  margin: 12px 0 0;
  color: #596579;
  line-height: 1.5;
}

.sync-button {
  min-height: 42px;
  padding: 0 18px;
  border: 0;
  border-radius: 8px;
  background: #2458d3;
  color: white;
  cursor: pointer;
  font: inherit;

